/**
 * Creates a Serdes for a specific class that preserves the class type. This implementation is a basic class wrapper and does not support any complex class structures. If you need custom serialization, it is recommended to create your own custom serdes.
 *
 * @param cls - The class constructor (must have no required parameters)
 *
 * @returns A Serdes that maintains the class type during serialization/deserialization
 *
 * @example
 * ```typescript
 * class User {
 *   name: string = "";
 *   age: number = 0;
 *
 *   greet() {
 *     return `Hello, ${this.name}`;
 *   }
 * }
 *
 * const userSerdes = createClassSerdes(User);
 *
 * // In a durable function:
 * const user = await context.step("create-user", async () => {
 *   const u = new User();
 *   u.name = "Alice";
 *   u.age = 30;
 *   return u;
 * }, { serdes: userSerdes });
 *
 * console.log(user.greet()); // "Hello, Alice" - methods are preserved
 * ```
 *
 * Limitations: - Class instances becomes plain objects and loses all class information - Constructor must have no parameters - Constructor side-effects will re-run during deserialization - Private fields (#field) cannot be serialized - Getters/setters are not preserved - Nested class instances lose their prototype
 *
 * For classes with Date properties, use createClassSerdesWithDates instead.
 *
 * @beta
 */

/**
 * Creates a custom Serdes for a class with special handling for Date properties. This implementation is a basic class wrapper and does not support any complex class structures. If you need custom serialization, it is recommended to create your own custom serdes.
 *
 * @param cls - The class constructor (must have no required parameters)
 *
 * @param dateProps - Array of property paths that should be converted to Date objects (supports nested paths like "metadata.createdAt")
 *
 * @returns A Serdes that maintains the class type and converts specified properties to Date objects
 *
 * @example
 * ```typescript
 * class Article {
 *   title: string = "";
 *   createdAt: Date = new Date();
 *   metadata: {
 *     publishedAt: Date;
 *     updatedAt: Date;
 *   } = {
 *     publishedAt: new Date(),
 *     updatedAt: new Date()
 *   };
 *
 *   getAge() {
 *     return Date.now() - this.createdAt.getTime();
 *   }
 * }
 *
 * const articleSerdes = createClassSerdesWithDates(Article, [
 *   "createdAt",
 *   "metadata.publishedAt",
 *   "metadata.updatedAt"
 * ]);
 *
 * // In a durable function:
 * const article = await context.step("create-article", async () => {
 *   const a = new Article();
 *   a.title = "My Article";
 *   return a;
 * }, { serdes: articleSerdes });
 *
 * console.log(article.getAge()); // Works! Dates are properly restored
 * ```
 *
 * Limitations: - Class instances becomes plain objects and loses all class information - Constructor must have no parameters - Constructor side-effects will re-run during deserialization - Private fields (#field) cannot be serialized - Getters/setters are not preserved - Nested class instances lose their prototype
 *
 * @beta
 */

