/**
 * Error a {@link DurableExecutionClient} throws to tell the SDK how to treat a failure.
 *
 * The SDK has to decide, for every failed client call, whether to end the invocation and let the execution resume later or to fail the execution outright. For the Lambda transport it infers this from the AWS SDK's error shape — HTTP status codes and exception names. A transport that does not produce AWS-shaped errors has no way to express the distinction, and would be treated as transient in every case, so a permanent failure would be retried until the execution timed out.
 *
 * Throwing this error states the classification directly, so any transport can express it without imitating another one's error shape.
 *
 * The scope is honoured wherever the error surfaces, not only on transport calls. In practice it is thrown by a {@link DurableExecutionClient}, but an EXECUTION-scoped error that escapes handler code fails the execution just the same. Handler code that wants an ordinary retryable failure should throw an ordinary error rather than this one.
 *
 * @example
 * ```typescript
 * class HttpDurableExecutionClient implements DurableExecutionClient {
 *   async checkpoint(params: CheckpointDurableExecutionRequest) {
 *     const response = await fetch(this.endpoint, { ... });
 *
 *     if (!response.ok) {
 *       throw new DurableExecutionClientError(
 *         `Checkpoint rejected: ${response.status}`,
 *         {
 *           // 4xx will not succeed on retry; 5xx might.
 *           scope:
 *             response.status < 500
 *               ? DurableExecutionClientErrorScope.EXECUTION
 *               : DurableExecutionClientErrorScope.INVOCATION,
 *         },
 *       );
 *     }
 *
 *     return response.json();
 *   }
 * }
 * ```
 *
 * @public
 */

